@heygarrett as a stopgap you could map any Telescope keybindings eg `<C-f>` to close miniFiles first
```
vim.api.nvim_create_autocmd('User', {
   pattern = 'MiniFilesBufferCreate',
   callback = function(args)
     local buf_id = args.data.buf_id
     vim.keymap.set('n', '<C-f>', '<cmd>normal q<C-f><cr>', { buffer = buf_id })
   end,
})
```

@IndianBoy42 Good idea! Here's a, perhaps unorthodox, solution. 😅

```lua
local group = vim.api.nvim_create_augroup("mini.files", { clear = true })
vim.api.nvim_create_autocmd("User", {
	pattern = "MiniFilesBufferCreate",
	desc = "define commands/keymaps for mini.files",
	group = group,
	callback = function(args)
		local buf_id = args.data.buf_id
		vim.api.nvim_create_autocmd("BufLeave", {
			group = group,
			buffer = buf_id,
			callback = function()
				vim.api.nvim_create_autocmd("BufEnter", {
					group = group,
					once = true,
					callback = function()
						if vim.bo.filetype ~= "minifiles" then
							vim.api.nvim_buf_call(buf_id, require("mini.files").close)
						end
					end,
				})
			end,
		})
	end,
})
```
